def _prettify_diagnosis_name(code: str) -> str:
    words = code.replace('_', ' ')
    return words[0].upper() + words[1:] if words else code

def rule(rid, branch, layer, conditions, conclusions, text, note='', cf=1.0):
    RULES.append({'id': rid, 'branch': branch, 'layer': layer, 'conditions': conditions, 'conclusions': conclusions, 'text': text, 'note': note, 'enabled': True, 'rule_type': 'intermediate', 'cf': cf})

def diag(rid, branch, conditions, diagnosis, severity, text, note='', layer=2):
    cf = 0.9 if len(conditions) >= 2 else 0.6
    RULES.append({'id': rid, 'branch': branch, 'layer': layer, 'conditions': conditions, 'conclusions': [{'fact': 'діагноз', 'value': diagnosis}], 'text': text, 'note': note, 'enabled': True, 'rule_type': 'diagnostic', 'cf': cf})
    if diagnosis not in DIAGNOSES:
        override = DIAGNOSIS_OVERRIDES.get(diagnosis, {})
        DIAGNOSES[diagnosis] = {'code': diagnosis, 'name': override.get('name', _prettify_diagnosis_name(diagnosis)), 'criticality': severity, 'description': override.get('description', f'Діагноз виводиться правилом {rid}: {text}'), 'recommendation': override.get('recommendation', 'Рекомендація ще не уточнена - додай через вкладку «Діагнози» в редакторі.')}
    else:
        DIAGNOSES[diagnosis]['criticality'] = max(DIAGNOSES[diagnosis]['criticality'], severity)
